const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/programs',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    view: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/programs?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&view=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/programs',
  headers: {'content-type': 'application/json'},
  body: {
    program: {
      name: 'Program A',
      address_freeform: '500 Construction Way, Santa Barbara',
      website: 'http://www.example.com',
      zip: 91013
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/programs"),
    Content = new StringContent("{\"program\":{\"name\":\"Program A\",\"address_freeform\":\"500 Construction Way, Santa Barbara\",\"website\":\"http://www.example.com\",\"zip\":91013}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
